import math, random, sys

# Physical constants (SI)
G = 6.67430e-11          # m^3 kg^-1 s^-2
c = 2.99792458e8        # m s^-1
hbar = 1.054571817e-34  # J s
k_B = 1.380649e-23      # J K^-1
M_sun = 1.98847e30      # kg

def hawking_temperature(M):
    """Hawking temperature of a Schwarzschild black hole (Kelvin)."""
    return hbar * c**3 / (8 * math.pi * G * k_B * M)

def planck_length():
    """Planck length (meters)."""
    return math.sqrt(hbar * G / c**3)

def random_mass():
    """Return a random mass between 5 and 50 solar masses."""
    return random.uniform(5, 50) * M_sun

def main():
    T = hawking_temperature(10 * M_sun)  # Example: 10 solar‑mass black hole
    l_p = planck_length()
    M_rand = random_mass()
    print(f"Hawking temperature for M = {10*M_sun:.2e} kg: {T:.3e} K")
    print(f"Planck length: {l_p:.3e} m")
    print(f"Random mass: {M_rand:.2e} kg")

if __name__ == "__main__":
    main()
